import{_ as o,o as t,c as i,ag as a}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"Changelog Notes","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/changelog.md","filePath":"en/guide/changelog.md","lastUpdated":null}'),r={name:"en/guide/changelog.md"};function n(d,e,l,c,s,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog-notes" tabindex="-1">Changelog Notes <a class="header-anchor" href="#changelog-notes" aria-label="Permalink to &quot;Changelog Notes&quot;">​</a></h1><p>This page explains the current documentation sync focus and provides an upgrade checklist. For complete release information, also check the per-module <code>CHANGELOG.md</code> files, default configuration files, and the release package you are using.</p><h2 id="corelib-4-5-11-item-2-5-9-safe-legacy-configured-item-migration" tabindex="-1">CoreLib 4.5.11 / Item 2.5.9: safe legacy configured-item migration <a class="header-anchor" href="#corelib-4-5-11-item-2-5-9-safe-legacy-configured-item-migration" aria-label="Permalink to &quot;CoreLib 4.5.11 / Item 2.5.9: safe legacy configured-item migration&quot;">​</a></h2><ul><li>Shared CoreLib GUI files and EmakiItem <code>items/</code> definitions now migrate legacy item fields before normal YAML parsing.</li><li>Legacy sources, amounts, names, lore, model data, enchantments, item flags, and hidden components are converted to <code>item.source</code>, <code>item.amount</code>, and <code>item.components</code>, including 1.21.5+ <code>custom_model_data</code> and <code>tooltip_display</code> mappings.</li><li>Canonical values win, <code>components.raw</code> nodes are skipped as a whole, non-target business fields remain unchanged, and repeated starts do not rewrite migrated files.</li><li>Exact original text is backed up before any change. Migrated output is written to a temporary file and parsed again; the source is replaced only after validation, and failures preserve or restore the original.</li><li>Backups are stored under each plugin data directory at <code>migration-backups/configured-item-format/&lt;timestamp&gt;/</code>. A full configuration backup is still recommended before production upgrades.</li></ul><h2 id="corelib-boundary-change-domain-protocols-moved-back-to-business-modules" tabindex="-1">CoreLib boundary change: domain protocols moved back to business modules <a class="header-anchor" href="#corelib-boundary-change-domain-protocols-moved-back-to-business-modules" aria-label="Permalink to &quot;CoreLib boundary change: domain protocols moved back to business modules&quot;">​</a></h2><p>CoreLib no longer owns domain protocols and extension points. Use the current owners:</p><ul><li>The item layer preview SPI (<code>ItemLayerPreviewProvider</code>, <code>ItemLayerPreviewRequest</code>, and related types) was removed from CoreLib and is now owned by <code>EmakiItemApi</code> in <code>emaki.jiuwu.craft.item.api.preview</code>.</li><li>Equipment skill PDC keys and their codec are now owned solely by <code>emaki.jiuwu.craft.skills.api.pdc.EquipmentSkillPdcCodec</code> in <code>EmakiSkillsApi</code>.</li><li>The attribute PDC and attribute service contract is now authoritative in <code>EmakiAttributeApi</code> (<code>emaki.jiuwu.craft.attribute.api.PdcAttributeApi</code> with the full <code>PdcAttributePayload</code>).</li><li>All CoreLib compatibility adapters were removed in CoreLib <code>4.6.7</code>: <code>SkillPdcGateway</code>, <code>PdcAttributeGateway</code>, and the mirror types <code>PdcAttributeApi</code>, <code>PdcAttributePayloadSnapshot</code>, and <code>EmakiAttributeBridge</code> no longer exist. External code still referencing them will throw <code>NoClassDefFoundError</code>.</li><li>These CoreLib adapters are retained for one synchronized release window only; new code should not depend on them.</li></ul><h2 id="current-documentation-sync-focus" tabindex="-1">Current documentation sync focus <a class="header-anchor" href="#current-documentation-sync-focus" aria-label="Permalink to &quot;Current documentation sync focus&quot;">​</a></h2><p>This documentation line has been rechecked against the current source tree for commands, permissions, configuration directories, and major runtime capabilities, together with the runtime boundaries and configuration structures below.</p><h3 id="runtime-boundary-and-configuration-sync-focus" tabindex="-1">Runtime boundary and configuration sync focus <a class="header-anchor" href="#runtime-boundary-and-configuration-sync-focus" aria-label="Permalink to &quot;Runtime boundary and configuration sync focus&quot;">​</a></h3><ul><li><strong>Platform and scheduling</strong><ul><li><code>paper-plugin.yml</code> descriptors now declare Paper 1.21.8+ and Folia support. CoreLib provides the Folia scheduler adapter, and business modules route delayed tasks, async work, GUI return-to-main-thread refreshes, and display refreshes through unified scheduling entry points.</li><li>Requirements now target Paper 1.21.8+ and include the current Folia support declaration.</li></ul></li><li><strong>GUI and item presentation</strong><ul><li>GUI slots use <code>item</code> as the current structured item-source field. Dynamic information, confirmation, and preview slots prefer template <code>item</code>, <code>display_name</code>, <code>lore</code>, and component settings.</li><li>EmakiGem inlay/open/upgrade GUIs no longer auto-fill the target item from the player&#39;s main hand or inventory when opened. Players must place target equipment and materials manually.</li><li>EmakiSkills skill panels, trigger selection, and EmakiStrengthen preview/confirmation dynamic slots now follow the same template-first GUI rule.</li></ul></li><li><strong>Attributes and PDC</strong><ul><li>Attribute supports ranged random values. Lore/PDC parsing can represent percentage and integer ranges, and snapshots keep minimum, maximum, and resolved values for ranged contributions.</li><li><code>variables</code> and <code>ea_attributes</code> are separated more strictly: variables are text/placeholder context, while real attribute output should use explicit <code>ea_attributes</code>.</li><li>Recent cleanup removed <code>ea_attribute_meta</code> logic; materials, gems, items, and strengthen configs should not rely on it as the current attribute metadata entry.</li></ul></li><li><strong>Cooking recipes</strong><ul><li>Recipe results now use the unified <code>result.&lt;branch&gt;.outputs/actions</code> structure. Success, early, over, undercooked, overcooked, and invalid branches follow the same model.</li><li>Recipe completion conditions were added, and station interaction keys were adjusted to the current source behavior.</li><li>Station floating text, display backend, and refresh configuration are part of the current configuration line.</li></ul></li><li><strong>Level</strong><ul><li>Added the EmakiLevel / EmakiLevelApi module for multiple level types, exp sources, requirements, PDC, PlaceholderAPI, CoreLib actions, MythicMobs drops, and EmakiAttribute contribution bridging.</li><li>VitePress now includes detailed Level module documentation, and the getting-started, introduction, and architecture pages include the progression module.</li></ul></li><li><strong>Forge / Gem / Strengthen / Item / Skills</strong><ul><li>Forge material effects show only payload fields for the selected effect type. <code>quality_modify</code> uses <code>tier</code>, and <code>capacity_bonus</code> uses <code>value</code>.</li><li>Gem items are refreshed from the current gem definition when obtained, after reloads, and when reconstructed inside GUIs.</li><li>Skills, Strengthen, Forge, Gem, and Item use the <code>es_skills</code> list form for skill effects in current examples and documentation.</li></ul></li></ul><h3 id="added-and-expanded" tabindex="-1">Added and expanded <a class="header-anchor" href="#added-and-expanded" aria-label="Permalink to &quot;Added and expanded&quot;">​</a></h3><ul><li><strong>Attribute</strong><ul><li>Configuration directory documentation for <code>config.yml</code>, <code>attribute_balance.yml</code>, <code>attributes/</code>, <code>damage_types/</code>, <code>conditions/</code>, and <code>lore_formats/</code>.</li><li>Scaling curve documentation for <code>logarithmic</code>, <code>sqrt</code>, and <code>piecewise_linear</code> rules.</li><li>Damage documentation now includes synthetic hit feedback when vanilla damage is intercepted.</li></ul></li><li><strong>Gem</strong><ul><li>Socket opener documentation for <code>socket_openers</code>, opener items, socket type filtering, and failure feedback.</li><li>Inlay success rate documentation for the current <code>inlay_success</code> structure.</li><li>Gem resonance documentation now covers <code>min_level</code>, <code>priority</code>, <code>exclusive_group</code>, and the actual <code>effects</code> object structure.</li></ul></li><li><strong>Skills</strong><ul><li>Action bar documentation for templates, update interval, and cast mode display.</li><li>Script engine limits, including per-phase action count and per-action target limits.</li><li>Passive trigger settings and <code>combo_attack</code> behavior.</li></ul></li><li><strong>Cooking</strong><ul><li>Command and permission documentation for <code>/ec debug</code>, oven, juicer, and fermentation barrel permissions.</li><li>Station documentation for display entities, display distance, refresh interval, wok animation, and scald damage.</li></ul></li><li><strong>Forge</strong><ul><li>Forge history documentation for audit records, auto-save, and troubleshooting.</li><li>Quality documentation keeps quality pools, guarantee counters, quality item metadata, and deterministic algorithm notes.</li></ul></li><li><strong>Strengthen</strong><ul><li>Branch tree documentation for branch recipe files and transfer design notes.</li></ul></li><li><strong>Item</strong><ul><li>Command documentation includes <code>/ei debug</code> and <code>emakiitem.debug</code>.</li></ul></li></ul><h3 id="removed-or-corrected" tabindex="-1">Removed or corrected <a class="header-anchor" href="#removed-or-corrected" aria-label="Permalink to &quot;Removed or corrected&quot;">​</a></h3><ul><li><strong>Gem commands</strong><ul><li>Removed old admin entries that are not in the current command router.</li><li>Current command set: <code>/emakigem gui &lt;inlay|open|upgrade&gt;</code>, <code>reload</code>, <code>inspect</code>, <code>clearstate</code>, and <code>debug</code>.</li><li>Current permissions: <code>emakigem.use</code>, <code>emakigem.reload</code>, <code>emakigem.admin</code>, and <code>emakigem.debug</code>.</li></ul></li><li><strong>Skills commands</strong><ul><li>GUI entry is <code>/eskills gui</code>.</li><li>Old trigger management commands were removed.</li><li><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code> is documented.</li><li><code>castmode</code> is documented as <code>/eskills castmode &lt;on|off|toggle&gt;</code>.</li></ul></li><li><strong>Cooking permissions</strong><ul><li>Juicer collect permission is <code>emakicooking.station.juicer.collect</code>.</li><li>Fermentation barrel start permission is <code>emakicooking.station.fermentation_barrel.start</code>.</li><li>Station permissions use the <code>emakicooking.station.*</code> form.</li></ul></li></ul><h2 id="module-version-lines" tabindex="-1">Module version lines <a class="header-anchor" href="#module-version-lines" aria-label="Permalink to &quot;Module version lines&quot;">​</a></h2><p>The current source tree does not use one single version number for every module. Prefer each module&#39;s <code>src/main/resources/config.yml</code> and <code>pom.xml</code> when upgrading:</p><table tabindex="0"><thead><tr><th>Module</th><th>Current default config version</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td><code>4.6.0</code></td></tr><tr><td>EmakiAttribute</td><td><code>4.6.0</code></td></tr><tr><td>EmakiForge</td><td><code>4.6.0</code></td></tr><tr><td>EmakiStrengthen</td><td><code>4.6.0</code></td></tr><tr><td>EmakiCooking</td><td><code>4.1.0</code></td></tr><tr><td>EmakiLevel</td><td><code>1.4.0</code></td></tr><tr><td>EmakiCodex</td><td><code>1.0.0</code></td></tr><tr><td>EmakiGem</td><td><code>2.6.0</code></td></tr><tr><td>EmakiSkills</td><td><code>2.6.0</code></td></tr><tr><td>EmakiItem</td><td><code>2.6.0</code></td></tr><tr><td>EmakiStorage</td><td><code>1.0.0</code></td></tr></tbody></table><p>The equipment skill PDC contract has been merged into <code>emaki-skills-api</code>; there is no longer a separate <code>emaki-skills-protocol</code> artifact.</p><p>Different version lines reflect separate release cadence, not feature importance.</p><h2 id="recommended-reading-order" tabindex="-1">Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to &quot;Recommended reading order&quot;">​</a></h2><ol><li>Read the target module overview page to confirm responsibilities and dependencies.</li><li>Read commands and permissions before configuring permission groups.</li><li>Read configuration directory or core feature pages to understand default files.</li><li>Read feature-specific pages such as socket openers, skill triggers, attribute scaling, forge quality, or cooking stations.</li><li>After editing configuration, verify with the module&#39;s reload, inspect, debug, or lint command if available.</li><li>Before upgrading a live server, test with real equipment and player data on a staging server.</li></ol><h2 id="upgrade-checklist" tabindex="-1">Upgrade checklist <a class="header-anchor" href="#upgrade-checklist" aria-label="Permalink to &quot;Upgrade checklist&quot;">​</a></h2><ul><li>Back up all <code>plugins/Emaki*/</code> configuration directories.</li><li>Back up player data, equipment data, Cooking station data, and economy data.</li><li>Do not blindly overwrite old configuration files; compare defaults and merge new fields manually. The CoreLib 4.5.11 / Item 2.5.9 configured-item migration is not a replacement for a full backup.</li><li>Check whether commands and permission nodes match the current documentation.</li><li>Check whether Attribute <code>hard_lock_damage</code> and environmental damage mapping fit your server.</li><li>Check whether Gem has merged <code>socket_openers</code>, <code>inlay_success</code>, and global <code>upgrade</code> configuration.</li><li>Check whether Skills has merged <code>actionbar</code>, <code>script_engine</code>, and <code>passive_trigger_settings</code>.</li><li>Check whether Cooking has merged oven, juicer, fermentation barrel station settings, GUI files, and permissions.</li><li>Check whether Forge quality, history, and condition failure strategies match your gameplay.</li><li>Check whether Item auto-update and repair configuration affect old items.</li></ul>',24)])])}const p=o(r,[["render",n]]);export{g as __pageData,p as default};
